import { ChangeDetectionStrategy, ChangeDetectorRef, Component } from '@angular/core';
import { RawMaterialService } from '../../services/raw-material-service';
import { CommonModule } from '@angular/common';
import { FormsModule, ReactiveFormsModule } from '@angular/forms';
import { RouterLink } from '@angular/router';
import { RawMaterial } from '../../models/invoice';

@Component({
  selector: 'app-raw-material',
  imports: [CommonModule, FormsModule, RouterLink],
  templateUrl: './raw-material.html',
  styleUrl: './raw-material.css',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class RawMaterialComponent {
RawMaterial: RawMaterial[] = [];
  searchTerm = '';

  constructor(private service: RawMaterialService, private cd: ChangeDetectorRef) {}

  ngOnInit() {
    this.service.getAllProducts().subscribe({
      next: (data) => {
        this.RawMaterial = data;
         this.cd.markForCheck();
        console.log("Products from backend:", this.RawMaterial);
      },
      error: (err) => console.error("Error fetching parties:", err)
    });
  }

  filteredProducts() {
    const term = this.searchTerm.toLowerCase();
    return this.RawMaterial.filter(r =>
      r.name.toLowerCase().includes(term) ||
      r.price.toPrecision().includes(term) 
    );
  }
}
